(* [comment removed for export] *)
Definition CELLS (T N : Z) (P : Z -> Prop) (dt : list (option deltX2)) : Prop :=
  Zlength dt = N /\ forall i, 0 <= i < N -> P i -> exists c, nth (Z.to_nat i) dt None = Some c /\ x2_cell_ok T c.

Lemma store_run_spec T N c : x2_cell_ok T c -> forall k dt p (P : Z -> Prop), 0 <= p -> p + Z.of_nat k <= N ->
  CELLS T N P dt -> exists dt', store_run k dt p c = Ok dt' /\ CELLS T N (fun i => P i \/ p <= i < p + Z.of_nat k) dt'.
