  Section MaxW.
    Variable maxW : Z.
    Hypothesis HM : 1 <= maxW <= tl /\ cw maxW <> 0 /\ forall m, maxW < m <= tl -> cw m = 0.
    Variable T : Z.
    Hypothesis HT : tl <= T <= 12.
    Let r : Z := T - tl - 1.
    Let Mn : nat := Z.to_nat maxW.

