      (forall j, (2 <= j <= w)%nat -> Znth (Z.of_nat j) rs0 = RP (j - 1)) ->
      (forall j, (j < 2)%nat \/ (S Mn < j)%nat -> (j < 15)%nat -> Znth (Z.of_nat j) rs0 = 0) ->
      exists rs0', rank_start2 fuel (Z.of_nat w) (RP w) rank rs0 = Ok (rs0', Nz) /\ Zlength rs0' = 15 /\
        (forall j, (2 <= j <= S Mn)%nat -> Znth (Z.of_nat j) rs0' = RP (j - 1)) /\
        (forall j, (j < 2)%nat \/ (S Mn < j)%nat -> (j < 15)%nat -> Znth (Z.of_nat j) rs0' = 0).
Proof.
