    Definition SEG2 (k : nat) (syms : list (option Z)) : Prop :=
      length syms = 256%nat /\
      forall w, 0 <= w <= 12 -> forall i, BK w <= i < BK w + cnt (firstn k ws) w ->
        exists v, nth (Z.to_nat i) syms None = Some v /\ 0 <= v < nbS.

    Lemma sort2_spec : forall fuel k rs0 syms, (k + fuel = Z.to_nat nbS)%nat -> Zlength rs0 = 15 ->
      (forall w, 0 <= w <= maxW -> Znth (w + 1) rs0 = BK w + cnt (firstn k ws) w) ->
      (forall j, 13 < j < 15 -> Znth j rs0 = Znth j rs0) ->
      Znth (maxW + 2) rs0 = Nz ->
      SEG2 k syms ->
      exists rs0' syms', sort2 fuel (Z.of_nat k) ws rs0 syms = Ok (rs0', syms') /\ SEG2 (Z.to_nat nbS) syms' /\ Zlength rs0' = 15 /\
        (forall w, 0 <= w <= maxW -> Znth (w + 1) rs0' = BK w + cw w) /\ (maxW < 12 -> Znth (maxW + 2) rs0' = Nz).
Proof.
