    Lemma rank_val_row_spec c : 1 <= c < 12 -> forall fuel (w : nat) rv, (1 <= w)%nat -> (w + fuel = S Mn)%nat -> RV0 rv ->
      (forall j, (1 <= j < w)%nat -> Znth (c * 13 + Z.of_nat j) rv = V0 j / 2^c) ->
      exists rv', rank_val_row fuel c (Z.of_nat w) rv = Ok rv' /\ RV0 rv' /\ ROW rv' c /\
        (forall c', 1 <= c' -> c' <> c -> ROW rv c' -> ROW rv' c').
Proof.
