      Lemma ffw_spec lvl baseSeq nbB le (b0 e : Z) :
        0 <= baseSeq < 256 -> 1 <= nbB <= T -> (lvl = 1 \/ lvl = 2) -> T - nbB = le -> 0 <= le -> 0 <= b0 -> e <= 256 ->
        (forall i, b0 <= i < e -> exists v, nth (Z.to_nat i) syms None = Some v /\ 0 <= v < nbS) ->
        forall fuel b dt base F, b0 <= b <= e -> e - b < Z.of_nat fuel -> 0 <= base <= F -> base + (e - b) * 2^le <= NL ->
          FR F dt -> exists dt', fill_for_weight fuel dt base b e nbB T baseSeq lvl syms = Ok (dt', base + (e - b) * 2^le)
                            /\ FR (Z.max F (base + (e - b) * 2^le)) dt'.
Proof.
