      Lemma level2_weights_spec Bs c baseSeq (minW : nat) : 0 <= Bs -> Bs + 2^(T - c) <= NL -> 0 <= baseSeq < 256 ->
        1 <= c <= T - 1 -> minBits <= c <= T - minBits -> (1 <= minW)%nat -> c - r <= Z.of_nat minW ->
        forall fuel (w2 : nat) dt F, (minW <= w2 <= S Mn)%nat -> (S Mn <= w2 + fuel)%nat ->
          Bs + V0 w2 / 2^c <= F <= Bs + 2^(T - c) -> FR F dt ->
          exists dt', level2_weights fuel dt Bs (Z.of_nat w2) (maxW + 1) T c rv syms rs0 (tl + 1) baseSeq = Ok dt'
                      /\ FR (Z.max F (Bs + 2^(T - c))) dt'.
Proof.
