(* [comment removed for export] *)
Section X2OK.
  Variables (L : Z) (src : list Z) (wkspSize : Z).
  Hypothesis RS : read_ncount_safe_stmt.
  Hypothesis HB : all_bytes src.
  Hypothesis HL : 1 <= L <= 12.
  Hypothesis Hwk : X2_WKSP_SIZE <= wkspSize.

  (* [comment removed for export] *)
  Theorem read_dtable_x2_safe :
    (exists tl cells ret, read_dtable_x2 L src wkspSize = Ok (tl, cells, ret)
       /\ x2_table_ok (x2_cells cells) tl /\ Zlength cells = 2^L /\ 1 <= tl <= L
       /\ (forall i, 0 <= i < 2^tl -> exists c, nth (Z.to_nat i) cells None = Some c))
